    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find rows that are mostly a single non-background color, and use the
    # fullest such row as the pattern for shorter rows of that color.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    candidates = {}
    for r, row in enumerate(grid):
        colors = [v for v in set(row) if v != bg]
        if len(colors) == 1:
            c = colors[0]
            cols = [j for j, v in enumerate(row) if v == c]
            candidates.setdefault(c, []).append((r, min(cols), max(cols), len(cols)))

    for c, rows in candidates.items():
        exemplar = max(rows, key=lambda x: x[3])
        _, left, right, _ = exemplar
        for r, lo, hi, _ in rows:
            if lo == left and hi < right:
                for j in range(hi + 1, right + 1):
                    if grid[r][j] == bg:
                        out[r][j] = 1
    return out
