    h, w = len(grid), len(grid[0])

    # Repeated-pattern case: recolor the extra background-colored cells in
    # the right-hand extension of repeated copies of the opening row pattern.
    if h >= 8 and w >= 4:
        for r in range(h):
            for period in range(1, min(10, h // 2) + 1):
                if r >= period and grid[r][:w-3] == grid[r-period][:w-3]:
                    for c in range(w-3, w):
                        if grid[r][c] != grid[r-period][c] and grid[r][c] == 8:
                            out[r][c] = 1
                    break

    # Horizontal stripe case: a shorter stripe is marked just beyond its end.
    for r, row in enumerate(grid):
        colors = set(row)
        if len(colors) == 1:
